// MAIRFM Car Mode — minimal Wave Mode for iPhone landscape.
(()=>{
'use strict';
if(window.MAIRCarModePrototype)return;
const $=id=>document.getElementById(id);
let overlay=null,isOpen=false;
function playbackState(){try{return window.JFMPlaybackState?.get?.()||{}}catch{return{}}}
function currentTrack(){const s=playbackState();return{title:String($('title')?.textContent||s.title||s.name||'MAIRFM').trim(),artist:String($('artist')?.textContent||s.artist||'').trim(),isPlaying:typeof s.isPlaying==='boolean'?s.isPlaying:!!s.expectedLive}}
function waveMarkup(){return `<svg viewBox="0 0 900 260" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="mairCarWaveGradient" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="#5930a9" stop-opacity=".08"/><stop offset=".5" stop-color="#b865ff"/><stop offset="1" stop-color="#53269a" stop-opacity=".08"/></linearGradient></defs><path d="M-20 145 C75 118 105 185 185 147 S310 65 394 136 S506 202 596 137 S725 82 920 148"/><path d="M-20 159 C94 210 137 84 230 151 S351 205 438 144 S563 75 650 143 S795 207 920 119"/><path d="M-20 119 C83 64 138 201 242 130 S367 78 458 146 S573 201 672 128 S806 73 920 151"/></svg>`}
function ensure(){if(overlay)return overlay;overlay=document.createElement('div');overlay.id='mairCarWaveOverlay';overlay.className='mair-car-wave-overlay';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','MAIRFM Car Mode');overlay.innerHTML=`<div class="mair-car-shell"><div class="mair-car-brand"><strong>MAIR<span>FM</span></strong></div><button type="button" class="mair-car-close" data-car-close aria-label="Car Mode sluiten">×</button><main class="mair-car-main"><div class="mair-car-wave-art">${waveMarkup()}</div><div class="mair-car-topline"><span class="mair-car-onair">ON AIR</span></div><section class="mair-car-track"><h1 id="mairCarTitle">MAIRFM</h1><div class="artist" id="mairCarArtist"></div><div class="mair-car-transport"><button type="button" class="mair-car-skip" data-car-transport="prev" aria-label="Vorige">◀︎</button><button type="button" class="mair-car-play" data-car-transport="play" aria-label="Play of pauze"><span id="mairCarPlayIcon">Ⅱ</span></button><button type="button" class="mair-car-skip" data-car-transport="next" aria-label="Volgende">▶︎</button></div></section><label class="mair-car-volume"><span>🔊</span><input id="mairCarVolume" type="range" min="0" max="100" value="55" aria-label="Volume"><output id="mairCarVolumeValue">55</output></label></main></div>`;document.body.appendChild(overlay);overlay.addEventListener('click',e=>{if(e.target.closest('[data-car-close]')){setOpen(false);return}const t=e.target.closest('[data-car-transport]');if(t)forwardTransport(t.dataset.carTransport)});const volume=$('mairCarVolume');volume?.addEventListener('input',()=>{const n=Math.max(0,Math.min(100,Number(volume.value)||0));if($('mairCarVolumeValue'))$('mairCarVolumeValue').value=String(n)});volume?.addEventListener('change',()=>setVolume(Number(volume.value)||0));return overlay}
function forwardTransport(action){const id=action==='play'?'play':action==='prev'?'prev':action==='next'?'next':'';const target=id?$(id):null;if(target){target.click();setTimeout(render,100);return true}if(action==='play'&&typeof window.JFMPlayback?.playPause==='function'){Promise.resolve(window.JFMPlayback.playPause()).finally(()=>setTimeout(render,100));return true}return false}
async function setVolume(percent){const value=Math.max(0,Math.min(100,Number(percent)||0));try{if(window.jfmSpotifyPlayer?.setVolume){await window.jfmSpotifyPlayer.setVolume(value/100);return true}}catch{}return false}
function render(){ensure();const t=currentTrack();if($('mairCarTitle'))$('mairCarTitle').textContent=t.title||'MAIRFM';if($('mairCarArtist'))$('mairCarArtist').textContent=t.artist||'';if($('mairCarPlayIcon'))$('mairCarPlayIcon').textContent=t.isPlaying?'Ⅱ':'▶︎'}
function setOpen(value){ensure();isOpen=!!value;overlay.classList.toggle('is-open',isOpen);document.body.classList.toggle('mair-car-mode-open',isOpen);if(isOpen){render();document.body.dataset.mairCarMode='1'}else delete document.body.dataset.mairCarMode;try{window.dispatchEvent(new CustomEvent('mair:car-mode',{detail:{open:isOpen}}))}catch{}}
function onKey(e){if(isOpen&&e.key==='Escape')setOpen(false)};document.addEventListener('keydown',onKey);['jfm:trackchange','jfm:playback-state','mair:channelchange'].forEach(name=>window.addEventListener(name,()=>{if(isOpen)render()}));
window.MAIRCarModePrototype={version:'wave-minimal-2026-08-29',open:()=>setOpen(true),close:()=>setOpen(false),toggle:()=>setOpen(!isOpen),render,setQueue:()=>{},setDJBreak:()=>{},setMix:()=>{},status:()=>({open:isOpen})};
})();